const fs = require('fs');
const { chromium } = require('playwright');
(async() => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1280, height: 1200 } });
  await page.setContent(fs.readFileSync('index.html', 'utf8'), { waitUntil: 'load' });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  const axeResult = await page.evaluate(async () => await window.axe.run());
  const wcag = axeResult.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = axeResult.violations.filter(v => v.tags.includes('best-practice'));
  const checks = await page.evaluate(() => ({
    h1Count: document.querySelectorAll('h1').length,
    mainCount: document.querySelectorAll('main').length,
    skipFirst: document.body.firstElementChild?.matches('a.skip-link[href="#maincontent"]'),
    hasNav: !!document.querySelector('nav[aria-label="Primary"]'),
    mainTabIndex: document.querySelector('main')?.getAttribute('tabindex'),
  }));
  const issues = [];
  if (checks.h1Count !== 1) issues.push({ id: 'single-h1', value: checks.h1Count });
  if (checks.mainCount !== 1) issues.push({ id: 'single-main', value: checks.mainCount });
  if (!checks.skipFirst) issues.push({ id: 'skip-link-first', value: checks.skipFirst });
  if (!checks.hasNav) issues.push({ id: 'primary-nav', value: checks.hasNav });
  if (checks.mainTabIndex !== '-1') issues.push({ id: 'main-tabindex', value: checks.mainTabIndex });
  console.log(JSON.stringify({ wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })), bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) })), checks, issues }, null, 2));
  await browser.close();
  process.exit(wcag.length || issues.length ? 1 : 0);
})().catch(err => { console.error(err); process.exit(1); });
